import {uid,initial,questions,issues} from './model.js';
export function emptyMergePack(){const p=initial(false);p.name='Объединённый пак';p.rounds[0].themes=[{id:uid(),name:'Первая тема',questions:[]}];return p;}
// Each copy owns fresh object and media IDs, even if the same source is added twice.
export function copyMergeItem(item,media){const copy=structuredClone(item),files=new Map(),refs=new Map();function visit(value){if(!value||typeof value!=='object')return;if(value.id)value.id=uid();if(value.mediaId){const old=value.mediaId;if(!media.has(old))throw Error('Не найден файл '+(value.filename||old));if(!refs.has(old))refs.set(old,uid());value.mediaId=refs.get(old);files.set(value.mediaId,media.get(old));}for(const child of Object.values(value))if(child&&typeof child==='object')Array.isArray(child)?child.forEach(visit):visit(child);}visit(copy);return {item:copy,media:files};}
export function addMergeItem(pack,media,source,roundIndex,themeIndex,targetId){const r=source.pack.rounds[roundIndex];if(!r)throw Error('Раунд больше не существует');const target=pack.rounds.find(x=>x.id===targetId);if(themeIndex!==null&&(!target||target.type!==r.type))throw Error('Переносите финальную тему в финал, обычную — в обычный раунд, а тему интерлюдии — в интерлюдию.');const result=copyMergeItem(themeIndex===null?r:r.themes[themeIndex],source.media);if(!result.item)throw Error('Тема больше не существует');if(themeIndex===null){const empty=pack.rounds.length===1&&pack.rounds[0].themes.length===1&&!pack.rounds[0].themes[0].questions.length;if(empty)pack.rounds=[];if(r.type==='final'&&pack.rounds.some(x=>x.type==='final'))throw Error('Финал уже добавлен. Перенесите нужные темы в существующий финал.');const finalIndex=pack.rounds.findIndex(x=>x.type==='final');pack.rounds.splice(finalIndex<0?pack.rounds.length:finalIndex,0,result.item);}else{if(target.themes.length===1&&!target.themes[0].questions.length)target.themes=[];if(target.type==='interlude')for(const q of result.item.questions)q.price=target.questionPrice;target.themes.push(result.item);}for(const [id,blob] of result.media)media.set(id,blob);return themeIndex===null?result.item.id:target.id;}
export function mergeIssues(pack,media){return [...(pack.rounds.filter(r=>r.type==='final').length>1?[{message:'Оставьте один финальный раунд'}]:[]),...issues(pack,media)];}
export function mergeMedia(pack,media){const used=new Set(questions(pack).flatMap(q=>[...q.steps,...(q.customRevealSteps||[])].map(s=>s.mediaId).filter(Boolean)));return new Map([...media].filter(([id])=>used.has(id)));}
